B.c0h=new A.ae("Pentobarbital coma",null,B.nf,null,null,null,null,null,null,null,null)
B.c2t=new A.ae("10 mg/kg load, then infusion at 1\u20136 mg/kg/hour",null,null,null,null,null,null,null,null,null,null)
B.c_w=new A.ae("Spinal cord injury",null,B.nf,null,null,null,null,null,null,null,null)
B.c_K=new A.ae("Consider Solumedrol: 30 mg/kg, then 5.4 mg/kg/hr for 23 h",null,null,null,null,null,null,null,null,null,null)
